sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({api, event, helpers, imports}) {
  const p = (event && event.payload) || {};
  if (typeof p.collapsed !== 'undefined') { api.setState('gnSideOpen', !(p.collapsed === true || p.collapsed === 'true')); return; }
  if (typeof p.selectedTabIndex !== 'undefined') { api.setState('gnSideOpen', true); }
}
